describe('Product Detail Page Navigation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com/');
  });

  it('should navigate to product detail page and return to catalogue', () => {
    // Login
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Verify login success
    cy.get('[data-testid="inventory-item"]').should('be.visible');
    cy.get('[data-testid="inventory-item"]').should('have.length.greaterThan', 0);

    // Navigate to product detail page
    cy.get('[data-testid="inventory-item-name"]').first().click();

    // Verify navigation to product detail page
    cy.url().should('include', 'inventory-item.html');
    cy.get('[data-testid="product-detail-title"]').should('be.visible');
    cy.get('[data-testid="product-detail-title"]').should('contain', 'Sauce Labs Backpack');

    // Return to catalogue
    cy.get('[data-testid="back-to-products"]').click();

    // Verify return to catalogue
    cy.url().should('include', 'inventory.html');
    cy.get('[data-testid="inventory-item"]').should('be.visible');
    cy.get('[data-testid="inventory-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="inventory-item"]').first().should('contain', 'Sauce Labs Backpack');
  });

  it('should handle navigation when product detail page is not found', () => {
    // Login
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Attempt to navigate to a non-existent product
    cy.get('[data-testid="inventory-item-name"]').eq(1).click();

    // Verify error message or fallback
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Product not found');

    // Verify user is still on inventory page
    cy.url().should('include', 'inventory.html');
    cy.get('[data-testid="inventory-item"]').should('be.visible');

    // Verify back button still works
    cy.get('[data-testid="back-to-products"]').click();
    cy.url().should('include', 'inventory.html');
  });
});
